// FUNCTION: BFME2 0x0071D9F0 size=227 name=?Clamp@VectorProcessorClass@@SAXPAVVector4@@PBV2@MMH@Z evidence=N:ledger
void VectorProcessorClass::Clamp(Vector4 *dst, const Vector4 *src, const float min, const float max, const int count)
{
	if (count <= 0)
		return;

	// Each component is clamped from below and then from above, both reading the source.
	for (int n = 0; n < count; n++)
	{
		const Vector4 &in = src[n];
		Vector4 &out = dst[n];

		out.X = (in.X < min) ? min : in.X;
		out.X = (in.X > max) ? max : in.X;

		out.Y = (in.Y < min) ? min : in.Y;
		out.Y = (in.Y > max) ? max : in.Y;

		out.Z = (in.Z < min) ? min : in.Z;
		out.Z = (in.Z > max) ? max : in.Z;

		out.W = (in.W < min) ? min : in.W;
		out.W = (in.W > max) ? max : in.W;
	}
}

