void VectorProcessorClass::MinMax(Vector3 *src, Vector3 &min, Vector3 &max, const int count)
{
	if (count <= 0) return;

	min = src[0];
	max = src[0];
	for (int n = 1; n < count; n++) {
		const Vector3 &v = src[n];
		min.X = (v.X > min.X) ? min.X : v.X;
		min.Y = (v.Y > min.Y) ? min.Y : v.Y;
		min.Z = (v.Z > min.Z) ? min.Z : v.Z;
		max.X = (max.X > v.X) ? max.X : v.X;
		max.Y = (max.Y > v.Y) ? max.Y : v.Y;
		max.Z = (max.Z > v.Z) ? max.Z : v.Z;
	}
}

